drawUndirectedPanel('a', 18, '(a)');
drawUndirectedPanel('b', 378, '(b)');

var c = draw.group();
panels.c = { group: c };
var cx = { s: 740, L: 875, R: 1060, t: 1160 };
var cy = { s: 222 };
var cLY = [52, 132, 222, 312, 402];
var cRY = [98, 202, 288, 374];

