for (i = 1; i <= 5; i++) node(cNodes, cx.L, cLY[i - 1]);
for (j = 1; j <= 4; j++) node(cNodes, cx.R, cRY[j - 1]);
node(cNodes, cx.t, cy.s, 't');
c.text('L').center(cx.L - 2, 475).font({ family: 'Times New Roman, serif', size: 31, style: 'italic' });
c.text('R').center(cx.R - 2, 475).font({ family: 'Times New Roman, serif', size: 31, style: 'italic' });
c.text('(c)').center(985, 511).font({ family: 'Times New Roman, serif', size: 30 });

function pathSegmentsFor(edge) {
