}

var hitGroup = c.group();
matchB_size3.forEach(function (edge, idx) {
  var pts = [cPoint('s'), cPoint('L', edge[0]), cPoint('R', edge[1]), cPoint('t')];
  var poly = hitGroup.polyline(pts.map(function (p) { return p.x + ',' + p.y; }).join(' '))
