function directedEdge(g, a, b) {
  var q = shortened(a, b, r + 2, r + 12);
  var ln = lineIn(g, q.x1, q.y1, q.x2, q.y2, black, 2.4, 1, true);
  ln.on('mousemove', function (ev) {
    showTooltip('Unit-capacity directed edge in the flow network.', ev);
  }).on('mouseleave', function () {
    hideTooltip();
  }).css('cursor', 'pointer');
  return ln;
}

for (var i = 1; i <= 5; i++) directedEdge(cEdges, cPoint('s'), cPoint('L', i));
bipEdges.forEach(function (e) {
  directedEdge(cEdges, cPoint('L', e[0]), cPoint('R', e[1]));
});
for (var j = 1; j <= 4; j++) directedEdge(cEdges, cPoint('R', j), cPoint('t'));

var cNodes = c.group();
makeNode(cNodes, cx.s, cy.s, 's');
for (i = 1; i <= 5; i++) makeNode(cNodes, cx.L, cLY[i - 1], '');
for (j = 1; j <= 4; j++) makeNode(cNodes, cx.R, cRY[j - 1], '');
makeNode(cNodes, cx.t, cy.s, 't');

labelText(c, 'L', cx.L - 4, 648, 42, true);
labelText(c, 'R', cx.R - 2, 648, 42, true);
labelText(c, '(c)', 1368, 727, 40, false);

function pathSegmentsFor(edge) {
  var L = edge[0], R = edge[1];
  return [
    [cPoint('s'), cPoint('L', L)],
    [cPoint('L', L), cPoint('R', R)],
    [cPoint('R', R), cPoint('t')]
  ];
}

function drawFlowHighlights(color, opacity) {
  panels.c.hl.clear();
  matchB_size3.forEach(function (edge) {
    pathSegmentsFor(edge).forEach(function (seg) {
      lineIn(panels.c.hl, seg[0].x, seg[0].y, seg[1].x, seg[1].y, color || matchBand, 15, opacity == null ? 0.78 : opacity, false);
    });
  });
}

function drawSelectedRoute(idx) {
  selectedRoute = idx;
  panels.c.selectedHL.clear();
  drawPanelBSelected(idx);
  if (idx == null) return;
  var edge = matchB_size3[idx];
  pathSegmentsFor(edge).forEach(function (seg, k) {
    lineIn(panels.c.selectedHL, seg[0].x, seg[0].y, seg[1].x, seg[1].y, selectedBand, k === 1 ? 22 : 19, 0.82, false);
  });
}

var hitGroup = c.group();
matchB_size3.forEach(function (edge, idx) {
  var pts = [cPoint('s'), cPoint('L', edge[0]), cPoint('R', edge[1]), cPoint('t')];
  var poly = hitGroup.polyline(pts.map(function (p) { return p.x + ',' + p.y; }).join(' '))
    .fill('none')
    .stroke({ color: '#ffffff', width: 34, opacity: 0.001, linecap: 'round', linejoin: 'round' })
    .attr({ 'pointer-events': 'stroke' });
  poly.on('mousemove', function (ev) {
    showTooltip('Click to inspect this one-unit s-to-t flow path.', ev);
  }).on('mouseleave', function () {
    hideTooltip();
  }).on('click', function () {
    drawSelectedRoute(idx);
    var e = matchB_size3[idx];
    showPopup('One unit of flow',
      'This highlighted route carries one unit from s to an L vertex, across the matching edge, and then to t. Its middle L-to-R segment is exactly one matched pair, so counting these paths counts matched pairs.');
  }).css('cursor', 'pointer');
});

function clearSelectedRoute() {
  selectedRoute = null;
  panels.c.selectedHL.clear();
  panels.b.selectedHL.clear();
}

function update_panelView(v) {
  currentPanel = v;
  var sel = document.getElementById('panelViewInput');
  if (sel && sel.value !== v) sel.value = v;
  if (v.indexOf('(c)') < 0) clearSelectedRoute();
}
window.update_panelView = update_panelView;

function drawAugmentCue(state) {
  panels.a.selectedHL.clear();
  if (state !== 'augmentLowerPath') return;
  lineIn(panels.a.selectedHL, panels.a.Lx, LYS[1], panels.a.Rx, RYS[0], selectedBand, 17, 0.55, false);
  lineIn(panels.a.selectedHL, panels.a.Lx, LYS[4], panels.a.Rx, RYS[2], selectedBand, 17, 0.55, false);
}

function update_augmentMatching(state) {
  augmentState = state;
  var out = document.getElementById('augmentStateVal');
  if (out) out.value = state;
  if (state !== 'size3') clearSelectedRoute();

  if (state === 'redirectTopMatch') {
    drawHighlightEdges(panels.a, matchA_redirect, matchBand, 0.78);
    drawAugmentCue(state);
  } else if (state === 'augmentLowerPath') {
    drawHighlightEdges(panels.a, matchA_redirect, matchBand, 0.58);
    drawAugmentCue(state);
  } else {
    drawHighlightEdges(panels.a, matchA_size2, matchBand, 0.78);
    drawAugmentCue(state);
  }

  drawHighlightEdges(panels.b, matchB_size3, matchBand, 0.78);
  drawFlowHighlights(matchBand, 0.78);
}
window.update_augmentMatching = update_augmentMatching;

var augOrder = ['size2', 'redirectTopMatch', 'augmentLowerPath', 'size3'];

function trigger_augmentMatching() {
  var k = augOrder.indexOf(augmentState);
  var next = augOrder[(k + 1) % augOrder.length];
  update_augmentMatching(next);

  if (next === 'redirectTopMatch') {
    update_panelView('Panel (a): size-2 matching');
    setNarration('A matched edge is redirected to a different L vertex while the matching still has size 2.');
  } else if (next === 'augmentLowerPath') {
    update_panelView('Panel (b): size-3 matching');
    setNarration('The orange cue marks the augmenting idea: redirect existing choices, then add another disjoint pair.');
  } else if (next === 'size3') {
    update_panelView('Panel (b): size-3 matching');
    setNarration('The matching now has three independent shaded L-to-R edges, so the matching cardinality is 3.');
  } else {
    update_panelView('Panel (a): size-2 matching');
    setNarration('Return to the original size-2 matching in panel (a).');
  }
}
window.trigger_augmentMatching = trigger_augmentMatching;

function setNarration(txt) {
  var n = document.getElementById('demoNarration');
  if (n) n.textContent = txt;
}

var demoSteps = [
  {
    title: 'Start with a matching',
    narration: 'Panel (a) shows a bipartite graph with two shaded edges. Because no shaded edges share an endpoint, they form a matching of cardinality 2.',
    state: { panelView: 'Panel (a): size-2 matching', augmentMatching: 'size2' }
  },
  {
    title: 'Redirect without increasing size yet',
    narration: 'Step once: one shaded choice is redirected to a different available L vertex while still using the same R endpoint. The matching property is preserved, but the cardinality has not increased yet.',
    state: { panelView: 'Panel (a): size-2 matching', augmentMatching: 'redirectTopMatch' }
  },
  {
    title: 'Use an augmenting route',
    narration: 'Step again: an alternating route frees one endpoint and adds a new matched pair. This is the move that raises the matching size.',
    state: { panelView: 'Panel (b): size-3 matching', augmentMatching: 'augmentLowerPath' }
  },
  {
    title: 'Arrive at a larger matching',
    narration: 'Panel (b) now has three shaded edges, still with no shared endpoints. The matching has grown from size 2 to size 3.',
    state: { panelView: 'Panel (b): size-3 matching', augmentMatching: 'size3' }
  },
  {
    title: 'Translate matching into flow',
    narration: 'Panel (c) adds a source s, a sink t, and directions on every edge. Each shaded matched edge in the bipartite graph becomes the middle edge of a shaded s-to-t route.',
    state: { panelView: 'Panel (c): flow network', augmentMatching: 'size3' }
  },
  {
    title: 'Inspect one unit of flow',
    narration: 'Click a shaded route in the flow network. The whole s-to-L-to-R-to-t path lights up, along with the single L-to-R matching edge it represents.',
    state: { panelView: 'Panel (c): flow network', augmentMatching: 'size3' }
  }
];

var stepIndex = 0;

function applyStep(i) {
  stepIndex = Math.max(0, Math.min(demoSteps.length - 1, i));
  var st = demoSteps[stepIndex];
  update_augmentMatching(st.state.augmentMatching);
  update_panelView(st.state.panelView);
  if (stepIndex !== 5) clearSelectedRoute();
  setNarration(st.narration);
  var lab = document.getElementById('stepLabel');
  if (lab) lab.textContent = (stepIndex + 1) + ' / ' + demoSteps.length;
}
function nextStep() { applyStep(stepIndex + 1); }
function prevStep() { applyStep(stepIndex - 1); }
window.nextStep = nextStep;
window.prevStep = prevStep;

bg.on('click', function () {
  hidePopup();
  hideTooltip();
  clearSelectedRoute();
});

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
